// Internal API methods describe existing permission metadata; external action
// routes keep their own HTTP methods and are dispatched by domain adapters.
func init() {
	for index := range operationDefinitions {
		operation := &operationDefinitions[index]
		switch operation.Scope {
		case "device:playback-stop", "device:talk:end", "device:broadcast:end":
			operation.SysAPIMethod = "DELETE"
		case "device:subscription:create", "device:subscription:cancel":
			operation.SysAPIMethod = "PATCH"
		case "device:config:refresh", "channel:video-params:refresh":
			operation.SysAPIMethod = "GET"
		case "device:config:apply", "channel:video-params:apply":
			operation.SysAPIMethod = "POST"
		}
	}
}
